INSERT INTO demo_community_preflight SELECT CASE WHEN NOT (NOT EXISTS(SELECT 1 FROM schema_migrations WHERE name='demo-community-20261026-v1')) OR (SELECT count(*) FROM guides WHERE (id=1 AND title='初到杭州，先留一个下午给西湖') OR (id=2 AND title='成都街巷漫步：院落之外，还有日常') OR (id=3 AND title='南阳人文散步：在卧龙岗读院落') OR (id=4 AND title='泉州古城的一段步行，从开元寺开始') OR (id=5 AND title='大理慢旅行：把古城和湖岸分开安排') OR (id=6 AND title='锦里怎么逛：先看建筑，再看热闹') OR (id=7 AND title='旅行前，怎样做一份不赶路的攻略') OR (id=21 AND title='杭州的另一种节奏：从湖岸走进山林') OR (id=22 AND title='给成都半天留白：茶座、公园与街巷') OR (id=23 AND title='南阳文化阅读：武侯祠、汉画馆与医圣祠') OR (id=24 AND title='从双塔到古桥，看泉州的两种尺度') OR (id=25 AND title='大理的三种观看方式：古城、古塔与湖岸') OR (id=101 AND title='第一次去杭州，两天怎样安排更从容') OR (id=102 AND title='西湖摄影散步：用三种距离看一段湖岸') OR (id=103 AND title='不太吃辣，也能安排一段成都食味之旅') OR (id=104 AND title='成都周末两日：公园、街巷与半天空白') OR (id=105 AND title='第一次看汉画像石：在汉画馆读懂三件作品') OR (id=106 AND title='南阳两天人文线：把院落、图像与人物分开读') OR (id=107 AND title='泉州古城半日：一座寺院与两种小吃的取舍') OR (id=108 AND title='从双塔到石桥：泉州古建观察的四个问题') OR (id=109 AND title='大理三天，不把环湖当作每天的任务') OR (id=110 AND title='洱海湖岸半日：给风景留一段真正的停留'))=22 THEN 1 ELSE 0 END;
